# Starting and Tracking Workflows in Cloudflare Agents

## Importing AgentWorkflow

```ts
import { AgentWorkflow } from "agents/workflows";
import type { AgentWorkflowEvent, AgentWorkflowStep } from "agents/workflows";
```

## Defining a Workflow

Extend `AgentWorkflow` with typed parameters:

```ts
export class ProcessingWorkflow extends AgentWorkflow<MyAgent, TaskParams> {
	async run(event: AgentWorkflowEvent<TaskParams>, step: AgentWorkflowStep) {
		const result = await step.do("process-data", async () => {
			return processData(event.payload.data);
		});

		await this.reportProgress({
			step: "process",
			status: "complete",
			percent: 0.5,
		});

		await step.reportComplete(result);
		return result;
	}
}
```

## Starting a Workflow from an Agent

The `runWorkflow()` signature:

```ts
const instanceId = await this.runWorkflow("PROCESSING_WORKFLOW", {
	taskId,
	data,
}, {
	metadata: { userId: "user-456", priority: "high" },
});
```

Returns a Promise resolving to the workflow instance ID string.

## Lifecycle Callbacks

Override these in your Agent class to handle workflow events:

```ts
class MyAgent extends Agent {
	async onWorkflowProgress(
		workflowName: string,
		instanceId: string,
		progress: unknown,
	) {
		this.broadcast(JSON.stringify({ type: "progress", progress }));
	}

	async onWorkflowComplete(
		workflowName: string,
		instanceId: string,
		result?: unknown,
	) {
		console.log(`${workflowName}/${instanceId} completed`);
	}

	async onWorkflowError(
		workflowName: string,
		instanceId: string,
		error: string,
	) {
		console.error(`${workflowName}/${instanceId} failed:`, error);
	}
}
```

## Wrangler Configuration

```toml
name = "my-app"
main = "src/index.ts"
compatibility_date = "2026-11-25"

[[durable_objects.bindings]]
name = "MY_AGENT"
class_name = "MyAgent"

[[workflows]]
name = "processing-workflow"
binding = "PROCESSING_WORKFLOW"
class_name = "ProcessingWorkflow"

[[migrations]]
tag = "v1"
new_sqlite_classes = [ "MyAgent" ]
```

## Key Step Methods

- `step.do(name, async fn)` — Execute durable operations with automatic retries
- `await this.reportProgress(...)` — Non-durable progress updates
- `await step.reportComplete(result)` — Durable completion marker

