  const snapshotIds = new Set(snapshot.map((message) => message.id));
  const restored = local.filter(
    (message) => bufferedIds.has(message.id) && !snapshotIds.has(message.id)
  );

  return restored.length === 0 ? snapshot : [...snapshot, ...restored];
}

