/**
 * Thin Workers AI client for Llama 3.3.
 *
 * Not using workers-ai-provider for text: Llama 3.3 streams each token in both
 * `response` and `choices[0].delta.content`, and workers-ai-provider 4.0.1
 * emits both, so every token appears twice. Here we read one field only.
 */

export const CHAT_MODEL = "@cf/meta/llama-3.3-70b-instruct-fp8-fast";

export type ChatMessage = { role: "system" | "user" | "assistant"; content: string };

/** Yields text deltas from a streamed Llama 3.3 chat completion. */
export async function* streamChat(
  ai: Ai,
  messages: ChatMessage[],
  opts: { maxTokens?: number; signal?: AbortSignal } = {}
): AsyncGenerator<string> {
  const stream = (await ai.run(CHAT_MODEL, {
    messages,
    stream: true,
    max_tokens: opts.maxTokens ?? 1024
  })) as ReadableStream<Uint8Array>;

  const reader = stream.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    while (true) {
      if (opts.signal?.aborted) return;
      const { done, value } = await reader.read();
      if (done) break;
      buffer += value;
      let newline: number;
      while ((newline = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, newline).trim();
        buffer = buffer.slice(newline + 1);
        if (!line.startsWith("data:")) continue;
        const data = line.slice(5).trim();
        if (data === "[DONE]") return;
        const text = deltaText(data);
        if (text) yield text;
      }
    }
  } finally {
    reader.releaseLock();
  }
}

function deltaText(data: string): string {
  try {
    const chunk = JSON.parse(data);
    // Prefer the OpenAI-style field; fall back to the native one. Never both.
    const choice = chunk.choices?.[0]?.delta?.content;
    if (typeof choice === "string") return choice;
    return typeof chunk.response === "string" ? chunk.response : "";
  } catch {
    return "";
  }
}

