import { AIChatAgent } from "@cloudflare/ai-chat";
import { routeAgentRequest } from "agents";
import { createUIMessageStream, createUIMessageStreamResponse, type UIMessage } from "ai";
import { streamChat, type ChatMessage } from "./llm";

/** Plain-text view of the chat history for the model. */
function toChatMessages(messages: UIMessage[]): ChatMessage[] {
  return messages
    .filter((m) => m.role === "user" || m.role === "assistant")
    .map((m) => ({
      role: m.role as "user" | "assistant",
      content: m.parts.map((p) => (p.type === "text" ? p.text : "")).join("")
    }))
    .filter((m) => m.content.trim());
}

/**
 * One Durable Object per chat. Step 0: a plain streamed Llama 3.3 reply.
 * The interpret → select → readiness → dispatch loop replaces this in step 2.
 */
export class ImageChatAgent extends AIChatAgent<Env> {
  async onChatMessage(_onFinish: unknown, options?: { abortSignal?: AbortSignal }) {
    const ai = this.env.AI;
    const history = toChatMessages(this.messages);
    const stream = createUIMessageStream({
      execute: async ({ writer }) => {
        const id = crypto.randomUUID();
        writer.write({ type: "text-start", id });
        const messages: ChatMessage[] = [
          { role: "system", content: "You are an assistant in an image creation and editing chat app." },
          ...history
        ];
        for await (const delta of streamChat(ai, messages, { signal: options?.abortSignal })) {
          writer.write({ type: "text-delta", id, delta });
        }
        writer.write({ type: "text-end", id });
      }
    });
    return createUIMessageStreamResponse({ stream });
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    return (await routeAgentRequest(request, env)) ?? new Response("Not found", { status: 404 });
  }
} satisfies ExportedHandler<Env>;

