:root {
  font-family: system-ui, sans-serif;
  color-scheme: light dark;
  --bg: #fff;
  --panel: #f4f4f5;
  --border: #d4d4d8;
  --muted: #71717a;
  --accent: #2563eb;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #18181b; --panel: #27272a; --border: #3f3f46; --muted: #a1a1aa; }
}
body { margin: 0; background: var(--bg); }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) 340px; height: 100vh; }
@media (max-width: 860px) { .layout { grid-template-columns: 1fr; } .canvas { display: none; } }

.chat { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--border); }
.chat header { display: flex; justify-content: space-between; padding: 12px 16px; font-weight: 600; border-bottom: 1px solid var(--border); }
.muted { color: var(--muted); font-weight: 400; font-size: 13px; }
.messages { flex: 1; overflow-y: auto; list-style: none; margin: 0; padding: 16px; display: flex; flex-direction: column; gap: 10px; }
.messages li { max-width: 80%; padding: 8px 12px; border-radius: 12px; display: flex; flex-direction: column; gap: 8px; }
.messages li p { margin: 0; white-space: pre-wrap; line-height: 1.45; }
.messages li.user { align-self: flex-end; background: var(--accent); color: white; }
.messages li.assistant { align-self: flex-start; background: var(--panel); }
.messages li.hint { align-self: center; color: var(--muted); text-align: center; max-width: 520px; }
.messages li.status { color: var(--muted); font-style: italic; }
.messages li.error { color: #dc2626; }
.messages .ask { font-weight: 500; }
.messages figure { margin: 0; }
.messages figure img { display: block; max-width: 360px; width: 100%; border-radius: 8px; }
.messages figcaption { font-size: 12px; color: var(--muted); margin-top: 4px; }

.options { display: flex; flex-wrap: wrap; gap: 8px; padding: 0 16px 8px; }
.options button { padding: 6px 12px; border-radius: 999px; border: 1px solid var(--accent); background: transparent; color: var(--accent); font: inherit; cursor: pointer; }

form { display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--border); }
form input { flex: 1; padding: 10px; border-radius: 8px; border: 1px solid var(--border); background: var(--bg); font: inherit; }
form button { padding: 10px 16px; border-radius: 8px; border: 0; background: var(--accent); color: white; font: inherit; cursor: pointer; }
form button.secondary { background: var(--panel); color: inherit; border: 1px solid var(--border); }
form button:disabled { opacity: 0.5; cursor: default; }

.canvas { padding: 16px; overflow-y: auto; }
.canvas h2 { font-size: 14px; margin: 0 0 8px; }
.canvas > img { width: 100%; border-radius: 8px; border: 1px solid var(--border); }
.thumbs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 8px; }
.thumbs a { display: flex; flex-direction: column; gap: 2px; text-decoration: none; color: var(--muted); font-size: 11px; }
.thumbs img { width: 100%; aspect-ratio: 1; object-fit: cover; border-radius: 6px; border: 1px solid var(--border); }

